import { Route } from '@angular/router';
import { MovieList } from './movie-list/movie-list';

export const appRoutes: Route[] = [
  { path: '', component: MovieList },
  // Placeholders for screens 2-5, implemented by later tickets.
  { path: 'screenings/:id/seats', children: [] },
  { path: 'screenings/:id/summary', children: [] },
  { path: 'screenings/:id/checkout', children: [] },
  { path: 'confirmation', children: [] },
  { path: '**', redirectTo: '' },
];

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};

import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { provideRouter, Router } from '@angular/router';
import { provideNativeDateAdapter } from '@angular/material/core';
import { appRoutes } from './app.routes';
import { MovieList } from './movie-list/movie-list';
import { toIsoDate, addDays, startOfDay } from './dates';
import { ComponentFixture } from '@angular/core/testing';

describe('tmp check', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting(), provideRouter(appRoutes), provideNativeDateAdapter()],
    });
  });

  it('routes', async () => {
    const router = TestBed.inject(Router);
    const http = TestBed.inject(HttpTestingController);
    await router.navigateByUrl('/screenings/1/seats');
    expect(router.url).toBe('/screenings/1/seats');
    await router.navigateByUrl('/nope/x');
    expect(router.url).toBe('/');
    http.match(() => true).forEach((r) => r.flush([]));
  });

  it('list states', async () => {
    const http = TestBed.inject(HttpTestingController);
    const router = TestBed.inject(Router);
    await router.navigateByUrl('/');
    const fixture: ComponentFixture<MovieList> = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    const el: HTMLElement = fixture.nativeElement;
    expect(el.querySelector('[data-testid="movies-loading"]')).toBeTruthy();
    expect(el.querySelectorAll('[data-testid="day-button"]').length).toBe(5);
    const today = toIsoDate(startOfDay(new Date()));
    expect(el.querySelector('[data-testid="day-button"][data-selected="true"]')?.getAttribute('data-date')).toBe(today);
    const reqs = http.match(() => true);
    expect(reqs.length).toBe(2);
    const movies = [
      { id: 1, title: 'A', genre: 'G', runtimeMinutes: 100, format: 'PL dubbing' },
      { id: 2, title: 'B', genre: 'H', runtimeMinutes: 90, format: 'PL subtitles' },
    ];
    const screenings = [
      { id: 11, movieId: 1, date: today, time: '19:00', occupiedSeats: [] },
      { id: 10, movieId: 1, date: today, time: '16:00', occupiedSeats: [] },
      { id: 12, movieId: 2, date: toIsoDate(addDays(startOfDay(new Date()), 1)), time: '10:00', occupiedSeats: [] },
    ];
    reqs.forEach((r) => r.request.url.endsWith('/movies') ? r.flush(movies) : r.flush(screenings));
    fixture.detectChanges();
    const cards = el.querySelectorAll('[data-testid="movie-card"]');
    expect(cards.length).toBe(1);
    const buttons = [...el.querySelectorAll('[data-testid="screening-button"]')].map((b) => b.textContent?.trim());
    expect(buttons).toEqual(['16:00', '19:00']);
    expect(el.querySelector('[data-testid="movie-runtime"]')?.textContent?.trim()).toBe('100 min');

    // choose tomorrow via URL
    await router.navigate([], { queryParams: { date: toIsoDate(addDays(startOfDay(new Date()), 1)) } });
    fixture.detectChanges();
    expect(el.querySelectorAll('[data-testid="movie-card"]').length).toBe(1);
    expect(el.querySelector('[data-testid="movie-title"]')?.textContent?.trim()).toBe('B');
    expect(el.querySelector('[data-testid="day-button"][data-selected="true"]')?.getAttribute('data-date')).toBe(toIsoDate(addDays(startOfDay(new Date()), 1)));

    // empty day
    await router.navigate([], { queryParams: { date: toIsoDate(addDays(startOfDay(new Date()), 3)) } });
    fixture.detectChanges();
    expect(el.querySelector('[data-testid="movies-empty"]')?.textContent?.trim()).toBe('No screenings on this day');
    expect(el.querySelectorAll('[data-testid="movie-card"]').length).toBe(0);

    // invalid date selects today
    await router.navigate([], { queryParams: { date: '2020-01-01' } });
    fixture.detectChanges();
    expect(el.querySelector('[data-testid="day-button"][data-selected="true"]')?.getAttribute('data-date')).toBe(today);
  });

  it('error and retry', async () => {
    const http = TestBed.inject(HttpTestingController);
    const router = TestBed.inject(Router);
    await router.navigateByUrl('/');
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    http.match(() => true).forEach((r) => r.flush('err', { status: 500, statusText: 'x' }));
    fixture.detectChanges();
    const el: HTMLElement = fixture.nativeElement;
    expect(el.querySelector('[data-testid="movies-error"]')?.textContent?.trim()).toBe('Failed to load movies');
    (el.querySelector('[data-testid="movies-retry-button"]') as HTMLButtonElement).click();
    fixture.detectChanges();
    expect(el.querySelector('[data-testid="movies-loading"]')).toBeTruthy();
    http.match(() => true).forEach((r) => r.flush([]));
    fixture.detectChanges();
    expect(el.querySelector('[data-testid="movies-empty"]')).toBeTruthy();
    expect(el.querySelector('[data-testid="movies-loading"]')).toBeNull();
  });
});

